// Nilad F5 — aggregate yesterday's WooCommerce orders + daily duplicate guard.
// Env (used by the upstream HTTP node, not this code): STORE_URL, WC_API_KEY, WC_API_SECRET.
// Input: [{ json: [ ...orders ] }] (defensive: { body: [ ...orders ] }).
// Output (dup): [{ json: { dup: true } }] — else ONE item:
//   { dup:false, orderCount, revenue, pendingCount, topProduct, dateStr, byStatus }
const item = $input.first();
const j = (item && item.json) || {};
const orders = Array.isArray(j) ? j : (Array.isArray(j.body) ? j.body : []);

const d = new Date(Date.now() - 86400000);
const p2 = (n) => String(n).padStart(2, '0');
const dateStr = d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate());

const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
if (sd.keys.includes('f5:' + dateStr)) return [{ json: { dup: true } }];

const ELIGIBLE = ['pending', 'processing', 'on-hold', 'completed'];
let revenue = 0;
let pendingCount = 0;
const byStatus = {};
const productQty = {};
for (const o of orders) {
  const status = String((o && o.status) || '');
  byStatus[status] = (byStatus[status] || 0) + 1;
  if (status === 'pending') pendingCount++;
  if (!ELIGIBLE.includes(status)) continue;
  revenue += parseFloat(o.total) || 0;
  const lines = Array.isArray(o.line_items) ? o.line_items : [];
  for (const li of lines) {
    const name = String((li && li.name) || '');
    if (!name) continue;
    productQty[name] = (productQty[name] || 0) + (Number(li.quantity) || 0);
  }
}
let topProduct = null;
for (const name of Object.keys(productQty)) {
  const qty = productQty[name];
  if (qty > 0 && (!topProduct || qty > topProduct.qty)) topProduct = { name, qty };
}
return [{
  json: {
    dup: false,
    orderCount: orders.length,
    revenue,
    pendingCount,
    topProduct,
    dateStr,
    byStatus
  }
}];

// Nilad F5 — build the owner Telegram text (Arabic, HTML-escaped) + idempotency key.
// Input: Aggregate yesterday output (dup:false path). Output ONLY: { tgText, key }
const j = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [
  '📊 ملخص يومي ' + esc(j.dateStr),
  'الطلبات: ' + esc(j.orderCount),
  'الإيراد: ' + esc(j.revenue) + ' ج.م',
  'المعلقة: ' + esc(j.pendingCount),
  j.topProduct
    ? 'الأكثر مبيعًا: ' + esc(j.topProduct.name) + ' (' + esc(j.topProduct.qty) + ')'
    : 'الأكثر مبيعًا: —'
];
const byStatus = j.byStatus || {};
for (const s of Object.keys(byStatus)) {
  lines.push(esc(s) + ': ' + esc(byStatus[s]));
}
return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', tgText: lines.join('\n'), key: 'f5:' + j.dateStr } }];

// Nilad F5 — record the sent report key (idempotency write, cap 100). Passthrough.
// Input: { tgText, key }. Output: same json unchanged.
const item = $input.first();
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const key = item.json.key;
if (key && !sd.keys.includes(key)) sd.keys.push(key);
if (sd.keys.length > 100) sd.keys.splice(0, sd.keys.length - 100);
return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', ...item.json } }];
